import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
import { Triangle } from "@remotion/shapes";
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); 

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type ReverseOverlayProps = Record<string, any>;

const ReverseOverlay: React.FC<ReverseOverlayProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  overlayColor = "#000000",
  iconColor = "#ffffff",
  durationInSeconds = 5,
  scale = 1,
  opacity = 0.65,
  pulseSpeed = 2,
}) => {
  useFontLoader(["Inter"]); // Basic font loader for consistency, though not used in shapes

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Handle canvas background transparency
  const canvasBg = transparentBackground ? "transparent" : backgroundColor;

  // --- Animation Logic ---

  // 1. Entrance Pop
  const entranceSpring = spring({
    frame,
    fps,
    config: {
      damping: 12,
      stiffness: 100,
    },
  });

  // 2. Pulse / Heartbeat for the background circle
  const pulse = Math.sin(frame / fps * pulseSpeed * Math.PI) * 0.05 + 1; // Oscillates between 0.95 and 1.05

  // 3. Arrow Animation (Staggered "Rewind" effect)
  // We want the arrows to light up or move slightly to indicate direction (Left)
  // Right arrow triggers first, then Left arrow, simulating flow <- <-
  
  const cycleDuration = fps / pulseSpeed;
  const arrowCycle = frame % cycleDuration;
  const arrowPhase = arrowCycle / cycleDuration; // 0 to 1

  // Right arrow (starts earlier in the sequence)
  const rightArrowOpacity = interpolate(
    arrowPhase,
    [0, 0.5, 1],
    [0.4, 1, 0.4],
    { extrapolateRight: "wrap" }
  );

  // Left arrow (starts later)
  const leftArrowOpacity = interpolate(
    arrowPhase,
    [0.2, 0.7, 1.2],
    [0.4, 1, 0.4],
    { extrapolateRight: "wrap" }
  );

  // Combined scale for the container
  const containerScale = entranceSpring * scale;

  // Calculate dynamic sizes based on video dimensions
  const minDim = Math.min(width, height);
  const circleSize = minDim * 0.4; // 40% of smallest screen dimension
  const triangleSize = circleSize * 0.35;
  const triangleGap = triangleSize * 0.1;

  // Convert hex to rgba for overlay if needed, but we use opacity prop on the div
  // Using simple style injection for the background circle

  return (
    <AbsoluteFill
      style={{
        backgroundColor: canvasBg,
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      {/* Main Container with Scale Animation */}
      <div
        style={{
          position: "relative",
          width: circleSize,
          height: circleSize,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          transform: `scale(${containerScale})`,
        }}
      >
        {/* Dark Circle Background */}
        <div
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            width: "100%",
            height: "100%",
            backgroundColor: overlayColor,
            borderRadius: "50%",
            opacity: opacity, // User defined base opacity
            transform: `scale(${pulse})`, // Subtle heartbeat
            boxShadow: `0 0 ${circleSize * 0.1}px rgba(0,0,0,0.5)`, // Soft shadow
          }}
        />

        {/* Icons Container - Centered */}
        <div
          style={{
            position: "relative",
            display: "flex",
            flexDirection: "row",
            alignItems: "center",
            justifyContent: "center",
            gap: triangleGap,
            // Offset slightly to the left visually because triangles are heavy on one side
            transform: `translateX(-${triangleSize * 0.1}px)`,
            zIndex: 1,
          }}
        >
          {/* Left Arrow */}
          <div style={{ opacity: leftArrowOpacity }}>
            <Triangle
              length={triangleSize}
              direction="left"
              fill={iconColor}
              cornerRadius={triangleSize * 0.05}
            />
          </div>

          {/* Right Arrow */}
          <div style={{ opacity: rightArrowOpacity }}>
            <Triangle
              length={triangleSize}
              direction="left"
              fill={iconColor}
              cornerRadius={triangleSize * 0.05}
            />
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default ReverseOverlay;